      name: 'inventory_search',
      description: 'Search inventory products by name. Searches product names case-insensitively.',
      inputSchema: {
        type: 'object',
        properties: {
          query: { type: 'string', description: 'Search query to match against product names (case-insensitive)' },
          limit: { type: 'integer', description: 'Maximum number of results to return (1 to 10)', minimum: 1, maximum: 10 }
